window.PLANNING_DATA={"contentRevision":"7887b21b01efc0766957"};

'use strict';
const WORKING=window.CALENDAR_DATA.edition==='working';
const D=window.CALENDAR_DATA, X=window.EXPERT_DATA, P=window.PLANNING_DATA;
const $=s=>document.querySelector(s);
const cats={wine:'Вино',music:'Музыка',gastro:'Гастрономия',art:'Искусство',city:'Город',partner:'Партнёры',expert:'Экспертная программа'};
const filterLabels={festival:'Фестивали',...cats};
const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const localDate=s=>new Date(s+'T12:00:00+03:00');
const pretty=s=>new Intl.DateTimeFormat('ru-RU',{day:'numeric',month:'long',timeZone:'Europe/Moscow'}).format(localDate(s));
const weekday=s=>new Intl.DateTimeFormat('ru-RU',{weekday:'long',timeZone:'Europe/Moscow'}).format(localDate(s));
const range=(a,b)=>a===b||!b?pretty(a):pretty(a)+' — '+pretty(b)+(b.slice(0,4)!=='2027'?' '+b.slice(0,4):'');
const state={view:'load',month:0,filters:[],query:'',density:'detail'};
const supplemental=X.events.map(e=>({...e,date:e.start,date_range_end:e.end,venue:e.place||'Площадка уточняется',display_time:'Время уточняется',categories:['expert'],supplemental:true,month_visible:true,public_description:e.description,sort_index:999999,calendar_status:'proposed',booking_status:'not_confirmed'}));
const allEvents=[...D.events,...supplemental];
const byId=new Map(allEvents.map(e=>[e.id,e]));
const supplementalYears=supplemental.map(e=>({...e,start_date:e.date,end_date:e.date_range_end,event_ids:[e.id],venues:[e.venue]}));
const allYears=[...D.year_events,...supplementalYears];
const normalize=s=>String(s||'').toLocaleLowerCase('ru-RU').replaceAll('ё','е');
function matches(e){return (!state.filters.length||state.filters.some(c=>(e.categories||[]).includes(c)))&&(!state.query||normalize([e.title,e.public_description||e.description,e.venue,...(e.venues||[]),e.date,e.start_date].join(' ')).includes(normalize(state.query)));}
function eventsOn(date){return allEvents.filter(e=>e.month_visible!==false&&(e.supplemental?e.date<=date&&(e.date_range_end||e.date)>=date:e.date===date)).sort((a,b)=>Number(a.supplemental)-Number(b.supplemental)||(a.sort_index??99999)-(b.sort_index??99999)||a.id.localeCompare(b.id));}
function yearInMonth(m){const days=D.month_metadata[m].days;return allYears.filter(e=>e.start_date<=days.at(-1)&&e.end_date>=days[0]&&matches(e)).sort((a,b)=>a.start_date.localeCompare(b.start_date)||Number(a.supplemental)-Number(b.supplemental)||a.id.localeCompare(b.id));}
function timeLabel(e,detailed=false){if(['sunset','after_bell'].includes(e.time_anchor))return e.display_time;if(detailed&&e.start_time)return e.start_time+(e.end_time?'–'+e.end_time:e.end_anchor==='sunset'?' — до заката':e.end_label?' — '+e.end_label:'');return e.display_time||e.start_time||'Время уточняется';}
function plain(s){return esc(s).replace(/\*\*(.*?)\*\*/g,'<strong>$1</strong>').replace(/\n/g,'<br>');}
function filterButton(k,extra=''){const on=state.filters.includes(k);return `<button type="button" class="filter-chip ${on?'selected':''} ${extra}" data-filter="${k}" aria-pressed="${on}">${on?'<span aria-hidden="true">✓</span>':`<span class="filter-dot filter-${k}" aria-hidden="true"></span>`}${esc(filterLabels[k])}</button>`;}
function monthOptions(){return '<option value="">Месяц</option>'+D.month_metadata.map((m,i)=>`<option value="${i}" ${state.view==='month'&&state.month===i?'selected':''}>${esc(m.name)}</option>`).join('');}
function renderFilters(){
 $('#filters').innerHTML=`<button class="all-filter ${state.filters.length?'':'selected'}" data-all aria-pressed="${!state.filters.length}">ВСЕ</button><button class="phone-filter" id="openFilters" aria-haspopup="dialog" aria-controls="filterDialog">Фильтры${state.filters.length?` <span>${state.filters.length}</span>`:''}</button><div class="desktop-filters">${Object.keys(filterLabels).map(k=>filterButton(k)).join('')}</div><label class="month-picker"><span class="sr-only">Месяц</span><select id="jumpMonth" aria-label="Месяц">${monthOptions()}</select></label><button class="reset-filters" data-all ${state.filters.length?'':'hidden'}>× Сбросить</button><div class="selected-filters">${state.filters.map(k=>`<button class="selected-chip" data-filter="${k}" aria-label="Убрать фильтр ${esc(filterLabels[k])}">${esc(filterLabels[k])} <span aria-hidden="true">×</span></button>`).join('')}</div>`;
 $('#filterChoices').innerHTML=Object.keys(filterLabels).map(k=>filterButton(k)).join('');
}
const regularYearIds=new Set(['jazz-jan','jazz-feb','jazz-mar','jazz-apr','jazz-may','jazz-jun','bell-start','summer-start','beach-start']);
function tone(e) {
 const categories = e.categories || [];
 if (e.is_festival) return 'festival';
 if (e.supplemental || categories.includes('expert')) return 'expert';
 const isMusic = e.event_ids
  ? e.event_ids.length > 0 && e.event_ids.every(id => byId.get(id)?.categories.includes('music'))
  : categories.includes('music');
 if (isMusic) return 'music';
 if (categories.includes('festival')) return 'festival';
 if (e.event_ids) return regularYearIds.has(e.id) ? 'regular' : 'major';
 const majorKind = ['cabaret','shum','cinematica','special_concert','ceremony','exhibition_opening'].includes(e.kind);
 return majorKind || (e.year_event_ids || []).some(id => !regularYearIds.has(id)) ? 'major' : 'regular';
}
function exhibitionPeriod(e){if(D.display_periods[e.id])return D.display_periods[e.id];const key=(e.year_event_ids||[]).find(id=>D.display_periods[id]);if(key)return D.display_periods[key];if(e.kind==='exhibition')return Object.values(D.display_periods).find(p=>e.date>=p.start&&e.date<=p.end);return null;}
function visiblePeriod(e){const p=exhibitionPeriod(e);return p?range(p.start,p.end):range(e.start_date||e.date,e.end_date||e.date_range_end);}
function periodNote(e){const p=exhibitionPeriod(e);if(p)return '<span class="event-period">Выставка: '+esc(range(p.start,p.end))+'</span>';return e.date_range_end&&e.date_range_end!==e.date?'<span class="event-period">'+esc(range(e.date,e.date_range_end))+'</span>':'';}
function yearCard(e){return `<button class="year-event tone-${tone(e)} ${e.supplemental?'expert-event':e.categories.includes('festival')?'festival-event':''}" data-year-event="${esc(e.id)}"><span class="year-date">${esc(visiblePeriod(e))}</span><strong>${esc(e.title)}</strong>${exhibitionPeriod(e)?`<span class="event-opening">Открытие ${esc(pretty(exhibitionPeriod(e).opening))}</span>`:''}<span class="event-venue">${esc(e.venues.join(' · '))}</span>${e.supplemental?'<span class="preliminary">'+(e.id==='exp_sparkling_session'?'Первый год не выбран · предложение':'Предварительная дата')+'</span>':e.status==='for_consideration'||e.calendar_status==='for_consideration'?'<span class="preliminary">На рассмотрении</span>':''}</button>`;}
function renderYear(){
 if(state.query){const results=allEvents.filter(matches).sort((a,b)=>a.date.localeCompare(b.date)||a.sort_index-b.sort_index);$('#loadView').innerHTML=results.length?`<div class="search-results">${results.map(e=>`<div class="search-date">${esc(range(e.date,e.date_range_end))}</div>${eventRow(e)}`).join('')}</div>`:empty();return;}
 $('#loadView').innerHTML='<div class="master-year">'+D.month_metadata.map((m,i)=>`<section class="master-month"><button class="year-month-heading" data-month="${i}"><span class="month-number">${String(i+1).padStart(2,'0')}</span><h2>${esc(m.name)}</h2><span aria-hidden="true">↗</span></button><button class="year-theme" data-theme="${i}">${esc(m.theme)}</button><div class="year-events">${yearInMonth(i).map(yearCard).join('')||'<p class="month-empty">Нет событий по выбранным фильтрам</p>'}</div><button class="month-open" data-month="${i}">Расписание по дням <span aria-hidden="true">→</span></button></section>`).join('')+'</div>';
}
function empty(){return '<p class="master-empty">Ничего не найдено. Попробуйте другое название или измените фильтры.</p>';}
function eventRow(e){return `<button class="agenda-event tone-${tone(e)} ${e.supplemental?'expert-event':''}" data-event="${esc(e.id)}"><span class="agenda-time">${esc(timeLabel(e))}${e.ends_next_day?'<small>до следующего дня</small>':''}</span><span class="agenda-info"><strong>${esc(e.title)}</strong>${periodNote(e)}<span class="event-venue">${esc(e.venue)}</span>${e.supplemental?'<span class="preliminary">'+(e.id==='exp_sparkling_session'?'Первый год не выбран · предложение':'Предварительная дата')+'</span>':e.status==='for_consideration'||e.calendar_status==='for_consideration'?'<span class="preliminary">На рассмотрении</span>':''}</span><span class="event-arrow" aria-hidden="true">↗</span></button>`;}
function dayProgram(date){return date>='2027-01-01'&&date<='2027-01-10'?'Новогодняя программа':'';}
function renderMonth(){
 const m=D.month_metadata[state.month];$('#monthTitle').textContent=m.name;$('#monthSelect').innerHTML=D.month_metadata.map((x,i)=>`<option value="${i}" ${i===state.month?'selected':''}>${esc(x.name)}</option>`).join('');$('#prevMonth').disabled=state.month===0;$('#nextMonth').disabled=state.month===11;
 $('#monthTheme').innerHTML=`<div class="month-theme-banner"><span>Тема месяца</span><strong>${esc(m.theme)}</strong></div>`;
 let count=0;
 $('#dailyAgenda').innerHTML=m.days.map(date=>{const events=eventsOn(date).filter(matches);count+=events.length;const weekend=[0,6].includes(localDate(date).getUTCDay());return `<section class="agenda-day ${weekend?'weekend':''}" data-date="${date}"><h3 class="day-heading"><span>${Number(date.slice(8))}</span><small>${esc(weekday(date))}</small></h3><div class="day-events">${dayProgram(date)?`<p class="day-program">${dayProgram(date)}</p>`:''}${events.length?events.map(eventRow).join(''):dayProgram(date)&&!state.filters.length&&!state.query?'':`<p class="day-empty">${state.filters.length||state.query?'Нет событий по выбранным фильтрам':'Отдельных событий нет'}</p>`}</div></section>`;}).join('');
 $('#resultNotice').hidden=count>0||(!state.query&&!state.filters.length);$('#resultNotice').innerHTML=count?'':empty();
}
function render(){
 if(!['load','month','plan'].includes(state.view))state.view=state.view==='loadMonth'?'month':'load';
 $('#loadView').hidden=state.view!=='load';$('#monthView').hidden=state.view!=='month';$('#planView').hidden=state.view!=='plan'||!WORKING;$('#resultNotice').hidden=true;$('#clearSearch').hidden=!state.query;
 document.querySelectorAll('[data-view]').forEach(b=>{const on=b.dataset.view===state.view;b.classList.toggle('active',on);b.setAttribute('aria-pressed',on);});
 renderFilters();if(state.view==='month')renderMonth();else if(state.view==='plan'&&WORKING)renderPlan();else renderYear();
}
function setView(view,m=state.month){state.view=view;state.month=Math.max(0,Math.min(11,Number(m)||0));history.replaceState(null,'','#'+(view==='month'?'month-'+(state.month+1):view));render();}
function parseHash(){const hash=location.hash;const m=hash.match(/^#(?:month|load-month)-(\d+)$/);if(m){state.view='month';state.month=Math.max(0,Math.min(11,+m[1]-1));}else if(hash==='#plan'&&WORKING)state.view='plan';else state.view='load';}
let dialogReturn=null;
function openDetail(title,html){dialogReturn=document.activeElement;$('#detailContent').innerHTML=`<h2 id="detailTitle" tabindex="-1">${esc(title)}</h2>${html}`;$('#detailDialog').setAttribute('aria-labelledby','detailTitle');if(!$('#detailDialog').open)$('#detailDialog').showModal();$('#detailDialog').scrollTop=0;$('#detailTitle').focus();}
function timingBlocks(e){const rows=e.phases||e.time_blocks||[];return rows.length?`<h3>Расписание</h3><ol class="timing-list">${rows.map(b=>`<li><strong>${esc(b.start_time||b.start||'')}${b.end_time||b.end?'–'+esc(b.end_time||b.end):''}</strong><div>${esc(b.label||b.title||b.description||'')}${b.venue?`<span>${esc(b.venue)}</span>`:''}</div></li>`).join('')}</ol>`:'';}
function eventDetails(e){const privateNotes=WORKING&&e.production_notes?.length?`<details><summary>Производственный план</summary>${e.production_notes.map(s=>`<p>${plain(s)}</p>`).join('')}</details>`:'';return `<div class="detail-facts tone-${tone(e)}"><span>${esc(range(e.date,e.date_range_end))} · ${esc(weekday(e.date))}</span><strong>${esc(timeLabel(e,true))}${e.ends_next_day?' · окончание на следующий день':''}</strong><span>${esc(e.venue)}</span></div>${e.supplemental?'<p class="detail-status">Экспертная программа · предварительные даты. Время и площадка согласуются.'+(e.id==='exp_sparkling_session'?' Первый год проведения не выбран.':'')+'</p>':WORKING?'<p class="detail-status">'+(e.calendar_status==='for_consideration'?'На рассмотрении':e.planning_status==='proposal'?'Предложение':'В плане')+(e.booking_status==='not_confirmed'?' · состав участников не подтверждён':'')+'</p>':e.calendar_status==='for_consideration'?'<p class="detail-status">На рассмотрении</p>':''}${exhibitionPeriod(e)?`<p class="detail-period">Выставка: ${esc(visiblePeriod(e))}. Открытие ${esc(pretty(exhibitionPeriod(e).opening))}.</p>`:''}<p>${plain(e.public_description||e.description)}</p>${(e.guest_conditions||[]).map(s=>`<p class="guest-condition">${esc(s)}</p>`).join('')}${e.film?`<p class="film-credit">${esc(e.film.title)} · ${esc(e.film.director)} · ${esc(e.film.year)}</p>`:''}${timingBlocks(e)}${e.booking_status==='not_confirmed'&&e.artist_options?.length?`<p>Варианты участников: ${e.artist_options.map(esc).join(', ')}. Участие не подтверждено.</p>`:''}${privateNotes}`;}
function openEvent(id){const e=byId.get(id);if(e)openDetail(e.title,eventDetails(e));}
function openYear(id){const y=allYears.find(e=>e.id===id);if(!y)return;if(y.supplemental){openEvent(id);return;}const events=y.event_ids.map(i=>byId.get(i)).filter(Boolean).sort((a,b)=>a.date.localeCompare(b.date)||a.sort_index-b.sort_index);openDetail(y.title,`<div class="detail-facts tone-${tone(y)}"><strong>${esc(visiblePeriod(y))}</strong>${exhibitionPeriod(y)?`<span>Открытие ${esc(pretty(exhibitionPeriod(y).opening))}</span>`:''}<span>${esc(y.venues.join(' · '))}</span></div><p>${plain(y.description)}</p>${y.status==='for_consideration'?'<p class="detail-status">На рассмотрении</p>':''}<div class="year-detail-events">${events.map(e=>`<div class="search-date">${esc(range(e.date,e.date_range_end))} · ${esc(weekday(e.date))}</div>${eventRow(e)}`).join('')}</div>`);}
function openTheme(m){if(!WORKING){setView('month',m);window.scrollTo({top:0});return;}const month=D.month_metadata[m];openDetail(month.theme,`<p>${esc(month.name)} 2027</p>${WORKING?`<p>${plain(month.program_logic)}</p>`:''}<button class="primary-action" data-month="${m}" data-close-detail>Расписание месяца →</button>`);}
let filterReturn=null;
function openFilters(){filterReturn=$('#openFilters');$('#filterDialog').showModal();}
$('#filterDialog').addEventListener('close',()=>{($('#openFilters')||filterReturn)?.focus();});
$('#detailDialog').addEventListener('close',()=>{if(dialogReturn?.isConnected)dialogReturn.focus();});
document.addEventListener('click',e=>{
 const b=e.target.closest('button,a');if(!b)return;
 if(b.id==='calendarHome'){e.preventDefault();state.filters=[];state.query='';$('#search').value='';setView('load');window.scrollTo({top:0});}
 if(b.hasAttribute('data-all')){state.filters=[];render();$('[data-all]')?.focus();}
 if(b.dataset.filter){const k=b.dataset.filter;const sheet=$('#filterDialog').open;state.filters=state.filters.includes(k)?state.filters.filter(x=>x!==k):[...state.filters,k];render();(sheet?$('#filterChoices [data-filter="'+k+'"]'):$('.selected-filters [data-filter="'+k+'"]')||$('[data-all]'))?.focus();}
 if(b.dataset.view){setView(b.dataset.view);window.scrollTo({top:0});}
 if(b.dataset.month!==undefined){if($('#detailDialog').open)$('#detailDialog').close();setView('month',b.dataset.month);window.scrollTo({top:0});}
 if(b.dataset.event)openEvent(b.dataset.event);
 if(b.dataset.yearEvent)openYear(b.dataset.yearEvent);
 if(b.dataset.theme!==undefined)openTheme(+b.dataset.theme);
 if(b.id==='openFilters')openFilters();
 if(b.hasAttribute('data-close-filters'))$('#filterDialog').close();
 if(b.matches('.dialog-close'))$('#detailDialog').close();
 if(b.id==='clearSearch'){state.query='';$('#search').value='';render();$('#search').focus();}
 if(b.id==='backYear')setView('load');
 if(b.id==='prevMonth'||b.id==='nextMonth')setView('month',state.month+(b.id==='prevMonth'?-1:1));
 if(b.id==='exportScenario')exportScenario();
});
for(const dialog of [$('#detailDialog'),$('#filterDialog')])dialog.addEventListener('click',e=>{if(e.target===dialog){const r=dialog.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)dialog.close();}});
document.addEventListener('change',e=>{if(['jumpMonth','monthSelect'].includes(e.target.id)&&e.target.value!==''){setView('month',+e.target.value);window.scrollTo({top:0});}});
$('#search').addEventListener('input',e=>{state.query=e.target.value;render();});
window.addEventListener('hashchange',()=>{parseHash();render();});
// The previous scenario remains byte-for-byte unchanged until the owner edits it.
const SCENARIO_KEY='belyi-mys-2027-resource-scenario-v1';let loadStorageOK=true,scenarioDirty=false,scenarioCorrupt=false;
let loadScenario={rows:{},capacity:{},extra:[]};
if(WORKING){try{const saved=localStorage.getItem(SCENARIO_KEY);if(saved){const value=JSON.parse(saved);if(!value.rows||!value.capacity||!Array.isArray(value.extra))throw Error('shape');loadScenario=value;}}catch{loadStorageOK=false;scenarioCorrupt=true;}}
function saveLoad(){if(!scenarioDirty)return loadStorageOK;try{localStorage.setItem(SCENARIO_KEY,JSON.stringify(loadScenario));scenarioDirty=false;return true;}catch{loadStorageOK=false;return false;}}
function plannerRows(){const prefix=state.month+':master:';return Object.keys(loadScenario.rows).filter(k=>k.startsWith(prefix)).map(k=>({key:k,event:byId.get(k.slice(prefix.length))})).filter(r=>r.event);}
function plannerTotal(v){return ['n','people','hours','prep'].every(k=>v[k]!==''&&v[k]!==undefined&&Number.isFinite(Number(v[k]))&&Number(v[k])>=0)?Number(v.n)*Number(v.people)*Number(v.hours)+Number(v.prep):null;}
function renderPlanner(){
 const rows=plannerRows(),complete=rows.filter(r=>plannerTotal(loadScenario.rows[r.key])!==null),total=complete.reduce((a,r)=>a+plannerTotal(loadScenario.rows[r.key]),0),old=Object.keys(loadScenario.rows).filter(k=>!k.includes(':master:')).length;
 const available=allEvents.filter(e=>e.date.slice(5,7)===String(state.month+1).padStart(2,'0')&&!rows.some(r=>r.event.id===e.id));
 return `<details class="team-planner"><summary>Рассчитать команду</summary><p>Общие смены и подготовку учитывайте один раз. Для события внутри фестиваля указывайте только дополнительную работу.</p><div class="planner-add"><select id="scenarioEvent" aria-label="Событие для расчёта"><option value="">Выбрать событие</option>${available.map(e=>`<option value="${esc(e.id)}">${esc(pretty(e.date)+' · '+e.title)}</option>`).join('')}</select><button id="addScenarioEvent" class="primary-action" ${loadStorageOK?'':'disabled'}>Добавить</button></div>${rows.map(r=>{const v=loadScenario.rows[r.key];return `<article class="scenario-row"><strong>${esc(pretty(r.event.date)+' · '+r.event.title)}</strong><div class="scenario-inputs">${[['n','Выпусков'],['people','Людей'],['hours','Часов'],['prep','Подготовка, чел.-ч']].map(([k,label])=>`<label>${label}<input type="number" min="0" step="${k==='n'||k==='people'?'1':'0.25'}" data-scenario-row="${esc(r.key)}" data-field="${k}" value="${esc(v[k]??'')}" aria-label="${esc(r.event.title+': '+label)}"></label>`).join('')}<span data-scenario-total="${esc(r.key)}">${plannerTotal(v)===null?'Не заполнено':plannerTotal(v)+' чел.-ч'}</span></div></article>`}).join('')}<p id="scenarioTotal">${rows.length?`Заполнено ${complete.length} из ${rows.length}. ${complete.length?'Итого: '+total+' чел.-ч'+(complete.length<rows.length?' (частичный расчёт)':''):'Трудозатраты не рассчитаны.'}`:'Расчёт не заполнен.'}</p>${old?`<p>Прежних строк: ${old}. Их значения сохранены в скачиваемом сценарии и не включены в новый расчёт.</p>`:''}<button class="primary-action" id="exportScenario">Скачать сохранённый сценарий</button><label class="scenario-import">Загрузить сценарий<input type="file" id="importScenario" accept=".json,application/json"></label><p id="scenarioMessage">${loadStorageOK?'Сохранено в этом браузере.':'Браузер не сохраняет расчёт. Скачайте сценарий перед закрытием.'}</p></details>`;
}
function refreshPlannerTotals(){const rows=plannerRows(),complete=rows.filter(r=>plannerTotal(loadScenario.rows[r.key])!==null);for(const r of rows){const cell=document.querySelector('[data-scenario-total="'+r.key+'"]');if(cell)cell.textContent=plannerTotal(loadScenario.rows[r.key])===null?'Не заполнено':plannerTotal(loadScenario.rows[r.key])+' чел.-ч';}$('#scenarioTotal').textContent=`Заполнено ${complete.length} из ${rows.length}. Итого: ${complete.reduce((a,r)=>a+plannerTotal(loadScenario.rows[r.key]),0)} чел.-ч${complete.length<rows.length?' (частичный расчёт)':''}`;}
document.addEventListener('input',e=>{const key=e.target.dataset.scenarioRow;if(WORKING&&key){loadScenario.rows[key][e.target.dataset.field]=e.target.value===''?'':Number(e.target.value);scenarioDirty=true;saveLoad();refreshPlannerTotals();}});
document.addEventListener('click',e=>{if(e.target.closest('#addScenarioEvent')&&WORKING){const id=$('#scenarioEvent').value;if(!byId.has(id))return;loadScenario.rows[state.month+':master:'+id]={n:1,people:'',hours:'',prep:''};scenarioDirty=true;saveLoad();renderPlan();$('.team-planner').open=true;}});

function exportScenario(){try{const raw=localStorage.getItem(SCENARIO_KEY);const text=scenarioCorrupt?(raw||''):JSON.stringify({format:'belyi-mys-resource-scenario-v1',contentRevision:D.contentRevision,scenario:loadScenario},null,2);const blob=new Blob([text],{type:'application/json'});const a=document.createElement('a');a.href=URL.createObjectURL(blob);a.download='Wine27_2027_Resource_Scenario.json';a.click();setTimeout(()=>URL.revokeObjectURL(a.href),1000);}catch{$('#scenarioMessage').textContent='Не удалось прочитать сохранённый расчёт.';}}
document.addEventListener('change',async e=>{if(!WORKING||e.target.id!=='importScenario'||!e.target.files?.[0])return;try{const data=JSON.parse(await e.target.files[0].text()),s=data.scenario;if(data.format!=='belyi-mys-resource-scenario-v1'||!s?.rows||!s.capacity||!Array.isArray(s.extra))throw Error('format');for(const row of Object.values(s.rows))if(!row||typeof row!=='object'||Object.entries(row).some(([k,v])=>!['n','people','hours','prep'].includes(k)||(v!==''&&(!Number.isFinite(Number(v))||Number(v)<0))))throw Error('values');loadScenario=s;scenarioCorrupt=false;scenarioDirty=true;saveLoad();renderPlan();$('.team-planner').open=true;}catch{$('#scenarioMessage').textContent='Не удалось прочитать сценарий. Выберите JSON, скачанный из календаря.';}});

function renderObject(value){if(value==null)return '';if(Array.isArray(value))return '<ul>'+value.map(v=>'<li>'+renderObject(v)+'</li>').join('')+'</ul>';if(typeof value==='object')return '<dl>'+Object.entries(value).map(([k,v])=>`<dt>${esc(k)}</dt><dd>${renderObject(v)}</dd>`).join('')+'</dl>';return plain(value);}
function renderPlan(){
 const notes=D.events.filter(e=>e.date.slice(5,7)===String(state.month+1).padStart(2,'0')&&e.production_notes?.length);
 $('#planView').innerHTML=`<div class="work-heading"><h2>Рабочий план</h2><select id="planMonth" aria-label="Месяц рабочего плана">${D.month_metadata.map((m,i)=>`<option value="${i}" ${i===state.month?'selected':''}>${esc(m.name)}</option>`).join('')}</select></div>${renderPlanner()}<details><summary>Условные программы</summary>${P.conditional_programs.map(c=>`<article><h3>${esc(c.format||c.title||c.id)}</h3>${renderObject(c)}</article>`).join('')}</details><details><summary>Особые условия и смена площадок</summary>${renderObject(P.special_conditions)}</details><details><summary>Экспертная программа: подготовка</summary>${renderObject(P.expertPreparation)}</details><details><summary>Экспертные проекты и статусы</summary>${renderObject(X.portfolio)}</details><details><summary>Правила программы</summary>${renderObject(P.rules)}</details><h3>${esc(D.month_metadata[state.month].name)}</h3>${notes.map(e=>`<article class="work-note"><button class="plain" data-event="${esc(e.id)}"><strong>${esc(e.date)} · ${esc(e.title)}</strong></button>${e.production_notes.map(n=>`<p>${plain(n)}</p>`).join('')}</article>`).join('')}`;
 $('#planMonth').onchange=e=>{state.month=+e.target.value;renderPlan();};
}
// Read-only surface for integrity and rendering checks; no additional recurrence engine.
window.WINE27_MASTER={eventsOn,yearInMonth,timeLabel,matches,allEvents,allYears,source:D,expert:X};
if(D.schema_version!=='wine27-master-2027/v1'||X.contentRevision!==D.contentRevision||P.contentRevision!==D.contentRevision||document.querySelector('meta[name="wine27-content"]')?.content!==D.contentRevision){$('#loadView').innerHTML='<p class="master-empty">Календарь обновляется. Обновите страницу через несколько секунд.</p>';}else{parseHash();render();}

/* Check for a published version without interrupting typing or losing the local scenario. */
(() => {
  const current=document.querySelector('meta[name="wine27-version"]')?.content;
  if(!current)return;
  const key='wine27-ui-before-update'+(WORKING?'-work':'');
  const status=document.getElementById('updateStatus');
  let pending=null,busy=false,lastInput=0;
  const say=text=>{if(status)status.textContent=text;};
  try{
    const stored=sessionStorage.getItem(key);
    if(stored){
      sessionStorage.removeItem(key);
      const ui=JSON.parse(stored);
      if(ui&&ui.version===current&&typeof state==='object'){
        if(['load','loadMonth','year','month','projects','expert','plan'].includes(ui.view))state.view=ui.view;
        if(Number.isInteger(ui.month)&&ui.month>=0&&ui.month<12)state.month=ui.month;
        const selected=Array.isArray(ui.filters)?ui.filters:[ui.category,...(ui.festivalsOnly===true?['festival']:[])];
        state.filters=[...new Set(selected.filter(k=>k==='festival'||Object.hasOwn(cats,k)))];
        state.density=ui.readabilityVersion===2&&ui.density==='compact'?'compact':'detail';
        state.expertTrack=['all','people','wines','recognition'].includes(ui.expertTrack)?ui.expertTrack:'all';
        state.expertTier=['all','core','development','reserve','conditional_session'].includes(ui.expertTier)?ui.expertTier:'all';
        state.planMonth=Number.isInteger(ui.planMonth)&&ui.planMonth>=0&&ui.planMonth<12?ui.planMonth:null;
        state.expertMonth=Number.isInteger(ui.expertMonth)&&ui.expertMonth>=0&&ui.expertMonth<12?ui.expertMonth:null;
        state.query=typeof ui.query==='string'?ui.query:'';
        document.getElementById('search').value=state.query;render();
        const planner=document.querySelector('.team-planner');if(planner&&ui.planner)planner.open=true;
        requestAnimationFrame(()=>window.scrollTo(0,Math.max(0,Number(ui.scroll)||0)));
      }
    }
  }catch{}
  document.addEventListener('input',()=>{lastInput=Date.now();});
  const editing=()=>document.activeElement?.matches('input,textarea,select,[contenteditable="true"]')||Date.now()-lastInput<2500;
  function apply(){
    if(!pending||document.visibilityState!=='visible')return;
    if(document.querySelector('#detailDialog')?.open||document.querySelector('#filterDialog')?.open){say('Новая версия готова · обновим после закрытия окна');return;}
    if(editing()){say('Новая версия готова · обновим после ввода');return;}
    if(WORKING&&typeof loadStorageOK!=='undefined'&&!loadStorageOK){say('Новая версия готова · сначала скачайте расчёт');return;}
    try{
      if(WORKING&&typeof saveLoad==='function'&&!saveLoad()){say('Сначала скачайте расчёт, затем обновите страницу');return;}
      const ui={version:pending,readabilityVersion:2,view:state.view,month:state.month,filters:state.filters,density:state.density,expertTrack:state.expertTrack,expertTier:state.expertTier,expertMonth:state.expertMonth,planMonth:state.planMonth,query:state.query,planner:!!document.querySelector('.team-planner')?.open,scroll:window.scrollY};
      sessionStorage.setItem(key,JSON.stringify(ui));
    }catch{say('Новая версия готова · обновите страницу вручную');return;}
    const next=new URL(location.href);next.searchParams.set('v',pending);
    say('Обновляем карту…');location.replace(next.href);
  }
  async function check(){
    if(busy||document.visibilityState!=='visible')return;
    if(pending){apply();return;}
    busy=true;
    try{
      const url=new URL('site-version.json',location.href);url.searchParams.set('_',Date.now());
      const res=await fetch(url,{cache:'no-store'});if(!res.ok)return;
      const data=await res.json();
      if(!/^[a-f0-9]{16}$/.test(data.version)||data.version===current){say('Автообновление включено');return;}
      // Pages/CDN may still be publishing. Wait until the HTML carries the same version.
      const htmlURL=new URL('index.html',location.href);htmlURL.searchParams.set('v',data.version);
      const page=await fetch(htmlURL,{cache:'no-store'});if(!page.ok)return;
      const html=await page.text();
      if(!html.includes(`name="wine27-version" content="${data.version}"`))return;
      pending=data.version;apply();
    }catch{say('Автообновление · ждём соединение');}finally{busy=false;}
  }
  document.addEventListener('focusout',()=>setTimeout(apply,2700));
  document.addEventListener('visibilitychange',check);
  window.addEventListener('online',check);
  setInterval(check,15000);setTimeout(check,1500);
})();
